//! `ter new`: a new project for a board, generated by the installed
//! xiao-generate, or by ter itself for the boards it has a template for
//! (`ter_gen::boards`, the Nucleo-F401RE).

use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde::Serialize;
use ter_gen::boards::{self, Board};
use ter_gen::new::{GENERATOR, Listing, NewArgs, listing_args};

use crate::output::{CliError, print_json};

#[derive(Serialize)]
struct Generated {
    board: String,
    hal: Option<String>,
    r#async: bool,
    name: String,
    dir: PathBuf,
    /// `xiao-generate`, or `ter` for a board ter generates itself.
    generator: &'static str,
    /// The xiao-generate command ter ran.
    #[serde(skip_serializing_if = "Option::is_none")]
    command: Option<String>,
}

fn generator() -> Result<PathBuf, CliError> {
    ter_gen::install::find_program(GENERATOR).ok_or_else(|| {
        CliError::new(
            "not_installed",
            format!(
                "{GENERATOR} is not installed, and ter new runs it. Install it with `ter install {GENERATOR}`."
            ),
        )
    })
}

/// With `--json` xiao-generate's own output goes to stderr, so stdout
/// stays one JSON document.
fn run_generator(args: &[OsString], json: bool) -> Result<(), CliError> {
    let mut command = Command::new(generator()?);
    command.args(args).stdin(Stdio::null());
    if json {
        command.stdout(std::io::stderr());
    }
    let status = command
        .status()
        .map_err(|e| CliError::new("generate_failed", format!("Could not run {GENERATOR}: {e}")))?;
    if status.success() {
        Ok(())
    } else {
        Err(CliError::new(
            "generate_failed",
            format!("{GENERATOR} could not generate the project ({status}); its message is above."),
        ))
    }
}

/// The generator's own .gitignore covers cargo; ter adds its folders.
fn add_gitignore(dir: &Path) {
    if dir.is_dir()
        && let Err(e) = ter_sdk::project::ensure_gitignore(dir)
    {
        eprintln!("warning: {e}");
    }
}

pub fn new(args: NewArgs, json: bool) -> Result<(), CliError> {
    if let Some(board) = boards::find(&args.board) {
        return new_own(board, args, json);
    }
    let gen_args = args.generator_args();
    run_generator(&gen_args, json)?;
    let dir = args.out_dir();
    add_gitignore(&dir);
    if json {
        print_json(&Generated {
            board: args.board,
            hal: args.hal,
            r#async: args.r#async,
            name: args.name,
            dir: std::path::absolute(&dir).unwrap_or(dir),
            generator: GENERATOR,
            command: Some(
                std::iter::once(GENERATOR.into())
                    .chain(gen_args.iter().map(|a| a.to_string_lossy().into_owned()))
                    .collect::<Vec<String>>()
                    .join(" "),
            ),
        });
    }
    Ok(())
}

/// A board ter has its own template for.
fn new_own(board: &Board, args: NewArgs, json: bool) -> Result<(), CliError> {
    let dir = board
        .write(&args)
        .map_err(|e| CliError::new("generate_failed", e))?;
    add_gitignore(&dir);
    if json {
        print_json(&Generated {
            board: args.board,
            hal: Some(board.hal.into()),
            r#async: false,
            name: args.name,
            dir: std::path::absolute(&dir).unwrap_or(dir),
            generator: "ter",
            command: None,
        });
    } else {
        println!(
            "Created {} for the {} ({}, {} template).",
            dir.display(),
            board.name,
            board.hal,
            board.template
        );
        println!(
            "Next: in that folder, `ter install targets {}` once, then `cargo run` flashes the board over its USB cable.",
            board.flashing
        );
    }
    Ok(())
}

/// The boards, HALs or templates `ter new` supports: xiao-generate's, as
/// it prints them, then ter's own. With `--json`, the text under
/// `listing`.
pub fn list(listing: Listing, board: Option<&str>, json: bool) -> Result<(), CliError> {
    // One of ter's boards: xiao-generate does not know it.
    if let Some(b) = board
        && boards::find(b).is_some()
    {
        let own = boards::listing(listing, board).unwrap_or_default();
        return print_listing(own, json);
    }
    let own = boards::listing(listing, None).unwrap_or_default();
    let args = listing_args(listing, board);
    // Without xiao-generate ter's own boards still list, with a note.
    let generator = match generator() {
        Ok(g) => g,
        Err(e) if board.is_none() => {
            eprintln!("{} The XIAO boards come from it.", e.message);
            return print_listing(own, json);
        }
        Err(e) => return Err(e),
    };
    if !json {
        run_generator(&args, false)?;
        if board.is_none() {
            println!();
            print!("{own}");
        }
        return Ok(());
    }
    let out = Command::new(generator)
        .args(&args)
        .stdin(Stdio::null())
        .output()
        .map_err(|e| CliError::new("generate_failed", format!("Could not run {GENERATOR}: {e}")))?;
    if !out.status.success() {
        return Err(CliError::new(
            "generate_failed",
            String::from_utf8_lossy(&out.stderr).trim().to_string(),
        ));
    }
    let mut text = String::from_utf8_lossy(&out.stdout).into_owned();
    if board.is_none() {
        if !text.is_empty() && !text.ends_with('\n') {
            text.push('\n');
        }
        text.push('\n');
        text.push_str(&own);
    }
    print_listing(text, true)
}

fn print_listing(text: String, json: bool) -> Result<(), CliError> {
    if json {
        print_json(&serde_json::json!({ "listing": text }));
    } else {
        print!("{text}");
    }
    Ok(())
}
